import { spawn } from 'node:child_process';
import { mkdir, writeFile, readFile } from 'node:fs/promises';
import { resolve, join } from 'node:path';
import assert from 'node:assert/strict';

// Everything generated by the experiment lives in the primary checkout's ignored research dir.
const root = resolve(import.meta.dirname, '..');
const scratch = join(root, '.research', `smoke-${Date.now()}`);
const home = join(scratch, 'codex-home');
await mkdir(home, { recursive: true });
await writeFile(join(scratch, 'fixture-input.txt'), 'phase0-tool-ok\n');
await writeFile(join(home, 'config.toml'), `model = "gpt-6-luna"
model_provider = "phase0"
approval_policy = "never"
sandbox_mode = "workspace-write"
[projects.${JSON.stringify(scratch.replaceAll('\\', '/'))}]
trust_level = "trusted"
[model_providers.phase0]
name = "Phase0 fixture"
base_url = "http://127.0.0.1:33210/v1"
wire_api = "responses"
requires_openai_auth = false
supports_websockets = false
env_key = "PHASE0_KEY"
request_max_retries = 0
stream_max_retries = 0
\n[mcp_servers.phase0]
command = "node"
default_tools_approval_mode = "approve"
args = [${JSON.stringify(join(root, 'scripts/fixture-mcp.mjs').replaceAll('\\', '/'))}, ${JSON.stringify(join(scratch, 'mcp-counter.txt').replaceAll('\\', '/'))}]
`);
const environment = { ...process.env, CODEX_HOME: home, PHASE0_KEY: 'phase0-fixture-key' };
const authHeaders = { Authorization: 'Bearer phase0-fixture-key' };
const server = spawn('dotnet', [join(root, 'tests/CodexPool.Probe/bin/Debug/net10.0/CodexPool.Probe.dll')], { cwd: root, windowsHide: true, stdio: ['ignore', 'pipe', 'pipe'] });
let serverOutput = ''; server.stdout.on('data', x => serverOutput += x); server.stderr.on('data', x => serverOutput += x);
const summary = { codexVersion: '', mockOnly: true, results: [] };
function run(args, name, timeout = 60000) {
  return new Promise((done, reject) => {
    const child = spawn('codex', args, { cwd: scratch, env: environment, windowsHide: true, stdio: ['ignore', 'pipe', 'pipe'] });
    let stdout = '', stderr = ''; const timer = setTimeout(() => { child.kill(); reject(new Error(`${name}: timeout`)); }, timeout);
    child.stdout.on('data', data => stdout += data); child.stderr.on('data', data => stderr += data);
    child.on('error', error => { clearTimeout(timer); reject(error); });
    child.on('close', async code => { clearTimeout(timer); await writeFile(join(scratch, `${name}.jsonl`), stdout); await writeFile(join(scratch, `${name}.stderr.txt`), stderr); done({ code, stdout, stderr }); });
  });
}
async function reset(scenario) {
  const response = await fetch(`http://127.0.0.1:33210/probe/reset/${scenario}`, { method: 'POST', headers: authHeaders }); assert.equal(response.status, 200);
}
async function status() { return (await fetch('http://127.0.0.1:33210/probe/status', { headers: authHeaders })).json(); }
try {
  let ready = false;
  for (let i = 0; i < 100; i++) {
    try { if ((await fetch('http://127.0.0.1:33210/health')).ok) { ready = true; break; } } catch {}
    if (server.exitCode !== null) throw new Error('Fixture exited before startup');
    await new Promise(r => setTimeout(r, 100));
  }
  assert(ready, 'Fixture started');
  summary.codexVersion = (await run(['--version'], 'version')).stdout.trim();
  for (const scenario of ['plain', 'quota', 'shell', 'mcp']) {
    await reset(scenario);
    const result = await run(['exec', '--strict-config', '--skip-git-repo-check', '--json', '-C', scratch, 'Complete the local protocol fixture.'], scenario);
    const observed = await status(); await writeFile(join(scratch, `${scenario}.status.json`), JSON.stringify(observed, null, 2));
    assert.equal(result.code, 0, `${scenario}: official Codex succeeds (see ignored stderr)`);
    assert(result.stdout.includes('phase0-ok'), `${scenario}: output reached Codex`);
    assert(observed.requests.every(x => !x.previousResponseId), 'HTTP requests have no remote continuation ID');
    if (scenario === 'quota') assert.deepEqual(observed.requests.map(x => x.account), ['A', 'B']);
    if (scenario === 'shell') {
      const executions = result.stdout.split(/\r?\n/).filter(Boolean).map(x => JSON.parse(x)).filter(x => x.item?.type === 'command_execution' && x.type === 'item.completed');
      if (executions.length > 0) {
        assert.equal(executions.length, 1, 'Official Codex executes the shell tool once');
        assert(executions[0].item.aggregated_output?.includes('phase0-tool-ok'), 'Harmless shell command succeeds');
      } else {
        assert(result.stderr.includes('blocked by policy'), 'Unexecuted tool has an explicit policy rejection');
        summary.shellExecution = 'pending: official CLI policy blocked harmless fixture command';
      }
      assert(observed.requests.some(x => x.resultCallIds.includes('phase0_shell_once')), 'Tool result returned to model');
      assert.equal(observed.requests.length, 2, 'One tool call/result followed by a new model request');
    }
    if (scenario === 'mcp') {
      assert.equal((await readFile(join(scratch, 'mcp-counter.txt'), 'utf8')).trim().split(/\r?\n/).length, 1, 'MCP side effect executes exactly once');
      assert(observed.requests.some(x => x.resultCallIds.includes('phase0_mcp_once')), 'MCP result returned to model');
    }
    summary.results.push({ scenario, passed: true, modelRequests: observed.requests.length, relays: observed.relays });
  }
  const plainEvents = (await readFile(join(scratch, 'plain.jsonl'), 'utf8')).split(/\r?\n/).filter(Boolean).map(x => JSON.parse(x));
  const threadId = plainEvents.find(x => x.type === 'thread.started')?.thread_id;
  assert(threadId, 'Official thread ID observed'); await reset('resume');
  const resumed = await run(['exec', 'resume', '--skip-git-repo-check', '--json', threadId, 'Continue the local fixture.'], 'resume');
  assert.equal(resumed.code, 0); assert(resumed.stdout.includes('phase0-ok'));
  const resumedStatus = await status();
  assert(resumedStatus.requests[0].inputCount > 1, 'Resume replays retained local context');
  summary.results.push({ scenario: 'resume', passed: true, inputCount: resumedStatus.requests[0].inputCount });
  await reset('plain');
  const rpc = spawn('codex', ['app-server', '--listen', 'stdio://'], { cwd: scratch, env: environment, windowsHide: true, stdio: ['pipe', 'pipe', 'pipe'] });
  const waiting = new Map(); const notices = []; let rpcLine = '', rpcId = 0, rpcErrors = '';
  rpc.stderr.on('data', data => rpcErrors += data);
  rpc.stdout.on('data', data => {
    rpcLine += data;
    while (rpcLine.includes('\n')) {
      const newline = rpcLine.indexOf('\n'); const line = rpcLine.slice(0, newline); rpcLine = rpcLine.slice(newline + 1);
      if (!line.trim()) continue;
      const message = JSON.parse(line);
      if (message.id !== undefined && !message.method) { const pending = waiting.get(message.id); if (pending) { waiting.delete(message.id); message.error ? pending.reject(new Error('RPC rejected')) : pending.resolve(message.result); } }
      else notices.push(message);
    }
  });
  function call(method, params) {
    return new Promise((resolveCall, rejectCall) => {
      const id = ++rpcId; const timer = setTimeout(() => { waiting.delete(id); rejectCall(new Error(`${method}: timeout`)); }, 30000);
      waiting.set(id, { resolve: value => { clearTimeout(timer); resolveCall(value); }, reject: error => { clearTimeout(timer); rejectCall(error); } });
      rpc.stdin.write(JSON.stringify({ id, method, params }) + '\n');
    });
  }
  async function notification(predicate, from) {
    for (let i = 0; i < 300; i++) { const match = notices.slice(from).find(predicate); if (match) return match; await new Promise(r => setTimeout(r, 100)); }
    throw new Error('RPC notification timeout');
  }
  try {
    await call('initialize', { clientInfo: { name: 'phase0_probe', version: '0.1.0' } }); rpc.stdin.write(JSON.stringify({ method: 'initialized' }) + '\n');
    const started = await call('thread/start', { cwd: scratch, model: 'gpt-6-luna' });
    let from = notices.length;
    await call('turn/start', { threadId: started.thread.id, input: [{ type: 'text', text: 'Create local fixture context.' }] });
    const initial = await notification(x => x.method === 'turn/completed', from); assert.equal(initial.params.turn.status, 'completed');
    from = notices.length; await call('thread/compact/start', { threadId: started.thread.id });
    await notification(x => x.method === 'thread/compacted' || x.method === 'item/completed' && x.params.item.type === 'contextCompaction', from);
    from = notices.length;
    await call('turn/start', { threadId: started.thread.id, input: [{ type: 'text', text: 'Continue compacted local fixture.' }] });
    const completed = await notification(x => x.method === 'turn/completed', from); assert.equal(completed.params.turn.status, 'completed');
    const compactStatus = await status(); assert.equal(compactStatus.requests.length, 3); assert(compactStatus.requests.every(x => x.route.endsWith('/responses')));
    summary.results.push({ scenario: 'compact', passed: true, modelRequests: compactStatus.requests.length, transport: 'responses-http' });
  } finally { rpc.kill(); await writeFile(join(scratch, 'compact.notifications.json'), JSON.stringify(notices, null, 2)); await writeFile(join(scratch, 'compact.stderr.txt'), rpcErrors); }
  await reset('partial');
  const partial = await run(['exec', '--strict-config', '--skip-git-repo-check', '--json', '-C', scratch, 'Complete the local protocol fixture.'], 'partial');
  const partialStatus = await status();
  assert.notEqual(partial.code, 0); assert(partialStatus.requests.every(x => x.account === 'A'), 'No cross-account replay after stream commitment');
  assert(partialStatus.relays.every(x => x.attempts === 1));
  summary.results.push({ scenario: 'partial', passed: true, officialClientRequests: partialStatus.requests.length, accountBRequests: 0 });
  await writeFile(join(scratch, 'summary.json'), JSON.stringify(summary, null, 2));
  console.log(JSON.stringify({ ...summary, evidenceDirectory: scratch }, null, 2));
} catch (error) {
  await writeFile(join(scratch, 'server.stderr.txt'), serverOutput);
  console.error(`${error.message}\nEvidence: ${scratch}`); process.exitCode = 1;
} finally { server.kill(); }
